namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Interfaces.Rest.Resources;

/// <summary>
///     Resource representing a reading relayed by an Edge Gateway. Body temperature is in degrees Celsius, activity
///     in index units, rumination in minutes and battery level in percent. An omitted metric is recorded as absent.
/// </summary>
/// <param name="ReadingId">The reading identifier generated by the device firmware.</param>
/// <param name="DeviceId">The device that captured the reading.</param>
/// <param name="RecordedAt">The instant the device captured the reading.</param>
/// <param name="BodyTemperature">The captured body temperature.</param>
/// <param name="ActivityIndex">The captured activity index.</param>
/// <param name="RuminationMinutes">The captured rumination minutes.</param>
/// <param name="BatteryLevel">The captured battery level in percent.</param>
/// <param name="Position">The captured GPS position.</param>
public record EdgeReadingResource(
    Guid ReadingId,
    Guid DeviceId,
    DateTimeOffset? RecordedAt,
    CapturedMetricResource? BodyTemperature,
    CapturedMetricResource? ActivityIndex,
    CapturedMetricResource? RuminationMinutes,
    CapturedMetricResource? BatteryLevel,
    CapturedPositionResource? Position);
